contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient, uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        require(caller != address(this), "caller must not be the test contract");
        require(recipient != address(c), "recipient cannot be c itself");

        // Setup: send Ether into c from this test contract.
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeBalanceRecipient = recipient.balance;

        // Impersonate the caller by making the withdrawAll call from a separate call context.
        // Since msg.sender is this InvMutTest contract for all direct calls, we cannot change it
        // without cheatcodes. Therefore we only test the owner case by setting owner to address(this).
        // However, the constructor of C was given some _owner. We cannot read it except via public getter.
        address ownerOfC = c.owner();

        bool reverted;
        // If owner is this contract, msg.sender == owner, so it should succeed.
        // Otherwise, it should revert because msg.sender != owner.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (ownerOfC == address(this)) {
            // Owner branch: should not revert, recipient should have received the entire balance.
            assert(!reverted && address(c).balance == 0 && recipient.balance == beforeBalanceRecipient + beforeBalanceC);
        } else {
            // Non-owner branch: should revert and state must be unchanged.
            assert(reverted && address(c).balance == beforeBalanceC && recipient.balance == beforeBalanceRecipient);
        }
    }

    receive() external payable {}
}

